<script setup>
import {computed,ref,watch} from 'vue';
import NativeOperationStatus from './NativeOperationStatus.vue';
import {nativeReceipt} from '../bot-native-transport.js';
import {buildMcpServer,referenceText,nativeValue,nativeMcpTools} from '../bot-native-data.js';
const props=defineProps({ui:{type:Object,required:true},bot:{type:Object,required:true},draft:{type:Object,required:true},enabled:Boolean,configBusy:Boolean});const emit=defineEmits(['save-config']);
const editor=ref(false),editingName=ref(''),form=ref({}),error=ref(''),serverName=ref(''),toolName=ref(''),argumentsText=ref('{}');
const state=computed(()=>props.ui.resource('mcp')),servers=computed(()=>props.draft.config.mcpServers||{}),evidence=computed(()=>nativeValue(state.value.data)),tools=computed(()=>evidence.value?.server===serverName.value?nativeMcpTools(state.value.data):[]);
const callResult=computed(()=>{const receipt=nativeReceipt({result:state.value.result});return receipt?.operation==='call'?receipt.data:null;});
function edit(name=''){const item=servers.value[name]||{};editingName.value=name;form.value={name,transport:item.transport||(item.url?'http':'stdio'),enabled:item.enabled!==false,command:item.command||'',argsText:(item.args||[]).join('\n'),url:item.url||'',envText:referenceText(item.env),headersText:referenceText(item.headers),includeText:(item.tools?.include||[]).join('\n'),excludeText:(item.tools?.exclude||[]).join('\n'),timeout:item.timeout??'',connectTimeout:item.connectTimeout??''};error.value='';editor.value=true;}
function apply(){try{const name=form.value.name.trim();if(!/^[a-z][a-z0-9_-]{0,63}$/.test(name)||name.startsWith('ziwei'))throw new Error('请使用小写 MCP 名称，紫薇保留名称不可编辑');if(!editingName.value&&Object.hasOwn(servers.value,name))throw new Error('已有同名 MCP，请使用编辑入口');props.draft.config.mcpServers[name]=buildMcpServer(form.value,servers.value[editingName.value]||{});editor.value=false;error.value='';}catch(value){error.value=value.message;}}
function remove(name){if(window.confirm('从此 Bot 的配置草稿移除 MCP '+name+'？'))delete props.draft.config.mcpServers[name];}
async function call(){try{const args=JSON.parse(argumentsText.value);if(!args||typeof args!=='object'||Array.isArray(args))throw new Error('工具参数须为 JSON 对象');error.value='';await props.ui.submit('mcp','call',{server:serverName.value,tool:toolName.value,arguments:args});}catch(value){error.value=value.message;}}
watch(()=>[props.ui.state.workspace,props.bot.id],()=>{editor.value=false;error.value='';serverName.value='';toolName.value='';argumentsText.value='{}';},{immediate:true});
watch(serverName,()=>{toolName.value='';argumentsText.value='{}';});
</script>
<template>
  <section class="native-section" aria-label="原生 MCP 与工具">
    <div class="native-toolbar"><div><h3>MCP 与工具</h3><p class="native-help">HTTP / SSE 与标准输入输出使用同一 Bot 配置草稿。保存后检查、启用，再核对实际加载和工具调用。</p></div><button class="bot-button" :disabled="!enabled||configBusy" @click="edit()">添加 MCP</button></div>
    <div class="native-list"><article v-for="(server,name) in servers" :key="name" class="native-list-row"><div><strong>{{name}}</strong><small>{{server.transport||(server.url?'http':'stdio')}} · {{server.enabled?'草稿中启用':'草稿中禁用'}}</small><small>{{server.url||server.command}}</small></div><div class="native-actions"><button class="bot-button" :disabled="configBusy" @click="edit(name)">编辑</button><button class="bot-button danger" :disabled="configBusy" @click="remove(name)">移除</button></div></article></div>
    <div v-if="editor" class="native-fields native-grid"><label>MCP 名称<input v-model="form.name" :disabled="Boolean(editingName)"/></label><label>连接方式<select v-model="form.transport"><option value="stdio">标准输入输出</option><option value="http">HTTP</option><option value="sse">SSE</option></select></label><template v-if="form.transport==='stdio'"><label class="wide">命令<input v-model="form.command" placeholder="例如 node"/></label><label class="wide">参数（每行一个）<textarea v-model="form.argsText" rows="3"/></label></template><template v-else><label class="wide">MCP 地址<input v-model="form.url" placeholder="https://..."/></label><label class="wide">HTTP header 引用<textarea v-model="form.headersText" rows="3" placeholder="Authorization=MY_AUTH_HEADER"/></label></template><label class="wide">环境变量引用<textarea v-model="form.envText" rows="3" placeholder="API_KEY=MY_LOCAL_API_KEY"/></label><label>允许工具（每行一个）<textarea v-model="form.includeText" rows="2"/></label><label>排除工具（每行一个）<textarea v-model="form.excludeText" rows="2"/></label><label>调用超时（秒）<input v-model="form.timeout" type="number" min="1" max="120"/></label><label>连接超时（秒）<input v-model="form.connectTimeout" type="number" min="1" max="60"/></label><label class="inline-check"><input v-model="form.enabled" type="checkbox"/>启用连接</label><div class="native-actions wide"><button class="bot-button primary" :disabled="configBusy" @click="apply">加入同一配置草稿</button><button class="bot-button" @click="editor=false">关闭编辑</button></div></div>
    <p v-if="error" role="alert" class="native-error">{{error}}</p><div class="native-actions"><button class="bot-button primary" :disabled="!enabled||configBusy" @click="emit('save-config')">保存全部配置并读回</button><button class="bot-button" :disabled="!enabled||state.loading||!serverName||!bot.config.mcpServers[serverName]" @click="ui.read('mcp',{server:serverName})">检查实际 MCP 加载</button></div>
    <p class="native-help">认证填写本机变量名；HTTP header 的变量值可包含完整认证格式。这里不保存或回显密钥。</p>
    <div class="native-fields native-grid"><label>服务名称<select v-model="serverName"><option value="">选择此 Bot 的 MCP</option><option v-for="(_,name) in servers" :key="name" :value="name">{{name}}</option></select></label><label>工具名称<input v-model="toolName" list="native-mcp-tools"/><datalist id="native-mcp-tools"><option v-for="tool in tools" :key="tool.name" :value="tool.name"/></datalist></label><label class="wide">工具参数 JSON<textarea v-model="argumentsText" rows="4"/></label></div><div class="native-actions"><button class="bot-button" :disabled="!enabled||ui.blocked()||bot.control_state!=='active'||bot.config.permissions.mode!=='execute'||!serverName||!toolName" @click="call">调用所选工具</button></div>
    <div v-if="tools.length" class="native-list"><article v-for="tool in tools" :key="tool.name" class="native-list-row"><div><strong>{{tool.name}}</strong><p>{{tool.description}}</p><details><summary>工具参数定义</summary><pre class="native-record">{{JSON.stringify(tool.parameters,null,2)}}</pre></details></div></article></div><div v-if="callResult" class="native-record" aria-label="MCP 工具返回"><strong>所选工具的原操作结果</strong><pre>{{JSON.stringify(callResult.result??callResult,null,2)}}</pre></div><p v-if="evidence?.reason" class="native-help">{{evidence.reason}}</p><NativeOperationStatus :state="state" @poll="ui.poll('mcp')" @recover="ui.recover('mcp')"/>
  </section>
</template>
